def compile_mjcf(facts, out):
    j = {'input_shaft':'input_spin','crank_arm':'input_spin','crank_handle_spindle':'input_spin','crank_grip':'input_spin','input_pinion':'input_spin','intermediate_shaft':'intermediate_spin','intermediate_driven_gear':'intermediate_spin','intermediate_stage2_pinion':'intermediate_spin','output_shaft':'output_spin','output_gear':'output_spin'}
    fixed = ['base','input_low_bearing','input_high_bearing','intermediate_low_bearing','intermediate_high_bearing','output_low_bearing','output_high_bearing']
    cmap = {'base':None,'input_low_bearing':None,'input_high_bearing':None,'intermediate_low_bearing':None,'intermediate_high_bearing':None,'output_low_bearing':None,'output_high_bearing':None}
    cmap.update(j)
    press = [
      ('input_shaft','crank_arm','relation/crank_to_input_shaft_press_fit','fit/input_shaft/shaft_axis/crank_arm/input_hub_bore','pair/crank_arm/input_shaft'),
      ('crank_arm','crank_handle_spindle','relation/handle_spindle_to_crank_press_fit','fit/crank_arm/handle_bore/crank_handle_spindle/spindle_axis','pair/crank_arm/crank_handle_spindle'),
      ('crank_handle_spindle','crank_grip','relation/grip_to_spindle_press_fit','fit/crank_handle_spindle/spindle_axis/crank_grip/grip_bore','pair/crank_grip/crank_handle_spindle'),
      ('input_shaft','input_pinion','relation/input_pinion_press_fit','fit/input_shaft/shaft_axis/input_pinion/shaft_bore','pair/input_pinion/input_shaft'),
      ('intermediate_shaft','intermediate_driven_gear','relation/intermediate_driven_gear_press_fit','fit/intermediate_shaft/shaft_axis/intermediate_driven_gear/shaft_bore','pair/intermediate_driven_gear/intermediate_shaft'),
      ('intermediate_shaft','intermediate_stage2_pinion','relation/intermediate_pinion_press_fit','fit/intermediate_shaft/shaft_axis/intermediate_stage2_pinion/shaft_bore','pair/intermediate_shaft/intermediate_stage2_pinion'),
      ('output_shaft','output_gear','relation/output_gear_press_fit','fit/output_shaft/shaft_axis/output_gear/shaft_bore','pair/output_gear/output_shaft')]
    meshes = [
      ('input_pinion','intermediate_driven_gear','relation/stage1_physical_mesh','fit/input_pinion/stage1_mesh/intermediate_driven_gear/stage1_mesh','pair/input_pinion/intermediate_driven_gear'),
      ('intermediate_stage2_pinion','output_gear','relation/stage2_physical_mesh','fit/intermediate_stage2_pinion/stage2_mesh/output_gear/stage2_mesh','pair/intermediate_stage2_pinion/output_gear')]
    bearings = [('input_low_bearing','input_shaft','pair/input_low_bearing/input_shaft'),('input_high_bearing','input_shaft','pair/input_high_bearing/input_shaft'),('intermediate_low_bearing','intermediate_shaft','pair/intermediate_low_bearing/intermediate_shaft'),('intermediate_high_bearing','intermediate_shaft','pair/intermediate_high_bearing/intermediate_shaft'),('output_low_bearing','output_shaft','pair/output_low_bearing/output_shaft'),('output_high_bearing','output_shaft','pair/output_high_bearing/output_shaft')]
    generic = [('input_shaft','intermediate_driven_gear'),('input_shaft','crank_grip'),('input_shaft','intermediate_stage2_pinion'),('input_shaft','crank_handle_spindle'),('crank_arm','intermediate_shaft'),('crank_handle_spindle','intermediate_shaft'),('intermediate_shaft','output_gear'),('crank_grip','intermediate_shaft'),('intermediate_driven_gear','output_shaft'),('input_low_bearing','input_pinion'),('input_high_bearing','input_pinion'),('crank_arm','input_pinion'),('input_pinion','intermediate_stage2_pinion'),('base','intermediate_driven_gear'),('intermediate_driven_gear','output_gear'),('intermediate_driven_gear','intermediate_stage2_pinion'),('input_low_bearing','intermediate_driven_gear'),('intermediate_low_bearing','intermediate_driven_gear'),('output_low_bearing','intermediate_driven_gear'),('input_high_bearing','intermediate_driven_gear'),('intermediate_high_bearing','intermediate_driven_gear'),('output_high_bearing','intermediate_driven_gear'),('crank_arm','intermediate_driven_gear'),('crank_handle_spindle','intermediate_driven_gear'),('crank_grip','intermediate_driven_gear'),('intermediate_high_bearing','intermediate_stage2_pinion'),('intermediate_high_bearing','output_gear'),('base','output_gear'),('output_high_bearing','output_gear'),('intermediate_low_bearing','output_gear'),('output_low_bearing','output_gear'),('crank_arm','output_gear'),('crank_handle_spindle','output_gear'),('crank_grip','output_gear'),('input_pinion','output_gear'),('input_high_bearing','output_gear'),('input_shaft','output_gear'),('input_low_bearing','output_gear'),('crank_arm','input_low_bearing'),('crank_arm','intermediate_low_bearing'),('crank_arm','crank_grip'),('base','crank_arm'),('crank_handle_spindle','intermediate_low_bearing'),('crank_grip','intermediate_low_bearing')]
    cd = []
    for a,b,r,f,p in press: cd.append({'pair':[a,b],'action':'exclude','reason':'Measured interference press fit is rigidly carried by one coordinate.','source_entity_ids':[r,'link/'+a,'link/'+b],'fact_ids':[f,p]})
    for a,b,r,f,p in meshes: cd.append({'pair':[a,b],'action':'exclude','reason':'Tooth contact is replaced by an ideal gear equality.','source_entity_ids':[r,'link/'+a,'link/'+b],'fact_ids':[f,p]})
    for a,b,p in bearings: cd.append({'pair':[a,b],'action':'exclude','reason':'Journal support is represented by the emitted hinge and must not resist spin.','source_entity_ids':['link/'+a,'link/'+b],'fact_ids':[p,'nearby/'+a+'/'+b]})
    for a,b in generic:
        x = a if a < b else b; y = b if a < b else a
        cd.append({'pair':[a,b],'action':'exclude','reason':'Positive real-mesh separation or disjoint AABB extent proves proxy false-contact risk without contact function.','source_entity_ids':['link/'+a,'link/'+b],'fact_ids':['pair/'+x+'/'+y,'nearby/'+x+'/'+y]})
    out.topology_plan({'coordinate_map':cmap,'tree_edges':[['','base'],['base','input_low_bearing'],['base','input_high_bearing'],['base','intermediate_low_bearing'],['base','intermediate_high_bearing'],['base','output_low_bearing'],['base','output_high_bearing'],['input_low_bearing','input_shaft'],['input_shaft','input_pinion'],['input_shaft','crank_arm'],['crank_arm','crank_handle_spindle'],['crank_handle_spindle','crank_grip'],['intermediate_low_bearing','intermediate_shaft'],['intermediate_shaft','intermediate_driven_gear'],['intermediate_shaft','intermediate_stage2_pinion'],['output_low_bearing','output_shaft'],['output_shaft','output_gear']],'closure_edges':[],'rigid_carried':[['input_shaft','input_pinion'],['input_shaft','crank_arm'],['crank_arm','crank_handle_spindle'],['crank_handle_spindle','crank_grip'],['intermediate_shaft','intermediate_driven_gear'],['intermediate_shaft','intermediate_stage2_pinion'],['output_shaft','output_gear']],'independent_coaxial':[],'transmissions':[{'driving_joint':'input_spin','driven_joint':'intermediate_spin','ratio':-0.3333333333333333},{'driving_joint':'intermediate_spin','driven_joint':'output_spin','ratio':-0.3333333333333333}],'contact_decisions':cd,'support_ground':True,'support_strategy':'Fixed base and bearing housings support three hinge coordinates; global ground remains enabled.'})
    out.body('base')
    for b in fixed[1:]: out.body(b,'base')
    out.body('input_shaft','input_low_bearing'); out.joint('input_shaft','input_spin',kind='hinge',axis=(0,0,1),pos_mm=(0,0,0),frame='local')
    out.body('input_pinion','input_shaft'); out.body('crank_arm','input_shaft'); out.body('crank_handle_spindle','crank_arm'); out.body('crank_grip','crank_handle_spindle')
    out.body('intermediate_shaft','intermediate_low_bearing'); out.joint('intermediate_shaft','intermediate_spin',kind='hinge',axis=(0,0,1),pos_mm=(0,0,0),frame='local')
    out.body('intermediate_driven_gear','intermediate_shaft'); out.body('intermediate_stage2_pinion','intermediate_shaft')
    out.body('output_shaft','output_low_bearing'); out.joint('output_shaft','output_spin',kind='hinge',axis=(0,0,1),pos_mm=(0,0,0),frame='local'); out.body('output_gear','output_shaft')
    out.joint_equality('stage1_gear','input_spin','intermediate_spin',-0.3333333333333333,reason='External 4.8 to 14.4 mm pitch-radius mesh.',sources=['transmission/stage1_three_to_one','relation/stage1_physical_mesh'],fact_ids=['fit/input_pinion/stage1_mesh/intermediate_driven_gear/stage1_mesh','pair/input_pinion/intermediate_driven_gear'])
    out.joint_equality('stage2_gear','intermediate_spin','output_spin',-0.3333333333333333,reason='External 4.8 to 14.4 mm pitch-radius mesh.',sources=['transmission/stage2_three_to_one','relation/stage2_physical_mesh'],fact_ids=['fit/intermediate_stage2_pinion/stage2_mesh/output_gear/stage2_mesh','pair/intermediate_stage2_pinion/output_gear'])
    for d in cd: out.exclude(d['pair'][0],d['pair'][1],d['reason'],d['source_entity_ids'],d['fact_ids'])
    for eid in facts['entity_ids']:
        if eid.startswith('link/'):
            out.decision(eid,action='emitted',generated_nodes=[eid[5:]],reason='Link mesh is emitted exactly once in the selected body tree.',fact_ids=[eid])
        else:
            out.decision(eid,action='represented_by',generated_nodes=['base'],reason='Authored placement, interface, port, transmission, or role is represented by the emitted machine topology.',fact_ids=[eid])
